{"comments": 1, "credits": [{"type": "reporter", "user": {"avatar_url": "https://avatars.githubusercontent.com/u/10262924?v=4", "events_url": "https://api.github.com/users/hawkeye64/events{/privacy}", "followers_url": "https://api.github.com/users/hawkeye64/followers", "following_url": "https://api.github.com/users/hawkeye64/following{/other_user}", "gists_url": "https://api.github.com/users/hawkeye64/gists{/gist_id}", "gravatar_id": "", "html_url": "https://github.com/hawkeye64", "id": 10262924, "login": "hawkeye64", "node_id": "MDQ6VXNlcjEwMjYyOTI0", "organizations_url": "https://api.github.com/users/hawkeye64/orgs", "received_events_url": "https://api.github.com/users/hawkeye64/received_events", "repos_url": "https://api.github.com/users/hawkeye64/repos", "site_admin": false, "starred_url": "https://api.github.com/users/hawkeye64/starred{/owner}{/repo}", "subscriptions_url": "https://api.github.com/users/hawkeye64/subscriptions", "type": "User", "url": "https://api.github.com/users/hawkeye64", "user_view_type": "public"}}], "cve_id": "CVE-2026-106105", "cvss": {"score": null, "vector_string": null}, "cvss_severities": {"cvss_v3": {"score": 0.0, "vector_string": null}, "cvss_v4": {"score": 8.4, "vector_string": "CVSS:4.0/AV:L/AC:L/AT:N/PR:L/UI:N/VC:H/VI:H/VA:N/SC:N/SI:N/SA:N"}}, "cwes": [{"cwe_id": "CWE-732", "name": "Incorrect Permission Assignment for Critical Resource"}], "description": "The `@quasar/ssl-certificate` development utility caches a combined PEM containing a generated private key and certificate without explicitly restricting its filesystem permissions. On systems with a typical process umask, the PEM can be readable by other local users. A local attacker with filesystem access could copy and reuse the private key to impersonate a development TLS endpoint in an environment that trusts the certificate.

The generated certificate was also unnecessarily CA-capable and included broad key usages beyond its localhost HTTPS purpose. Its IPv6 loopback entry was encoded as a DNS name rather than an IP subject alternative name.

The remediation writes and repairs the cached PEM with owner-only permissions on supported platforms, generates a non-CA server-auth leaf certificate with constrained key usage, corrects the IPv6 loopback SAN, and bases cache expiry on content modification time so permission metadata changes cannot extend the certificate lifetime. This issue does not expose the key remotely by itself; exploitation requires another local user to be able to read the cached PEM file.", "ghsa_id": "GHSA-fh39-c73x-5pjv", "github_reviewed_at": "2026-10-07T16:16:18Z", "html_url": "https://github.com/advisories/GHSA-fh39-c73x-5pjv", "identifiers": [{"type": "GHSA", "value": "GHSA-fh39-c73x-5pjv"}, {"type": "CVE", "value": "CVE-2026-106105"}], "nvd_published_at": "2026-10-06T18:16:51Z", "published_at": "2026-10-07T16:16:18Z", "references": ["https://github.com/quasarframework/quasar/security/advisories/GHSA-fh39-c73x-5pjv", "https://nvd.nist.gov/vuln/detail/CVE-2026-106105", "https://github.com/quasarframework/quasar/commit/b719460aa78e88714b8a1b7ca68267234d217575", "https://github.com/quasarframework/quasar/releases/tag/@quasar/app-vite-v3.3.0", "https://github.com/quasarframework/quasar/releases/tag/@quasar/cli-v5.0.4", "https://github.com/advisories/GHSA-fh39-c73x-5pjv"], "repository_advisory_url": "https://api.github.com/repos/quasarframework/quasar/security-advisories/GHSA-fh39-c73x-5pjv", "severity": "high", "source_code_location": "https://github.com/quasarframework/quasar", "summary": "Quasar Framework: Development TLS private keys are cached with overly permissive filesystem permissions", "type": "reviewed", "updated_at": "2026-10-07T16:16:19Z", "url": "https://api.github.com/advisories/GHSA-fh39-c73x-5pjv", "vulnerabilities": [{"first_patched_version": "2.1.0", "package": {"ecosystem": "npm", "name": "@quasar/ssl-certificate"}, "vulnerable_functions": [], "vulnerable_version_range": "<= 2.0.0"}, {"first_patched_version": "5.0.4", "package": {"ecosystem": "npm", "name": "@quasar/cli"}, "vulnerable_functions": [], "vulnerable_version_range": "<= 5.0.3"}, {"first_patched_version": "3.3.0", "package": {"ecosystem": "npm", "name": "@quasar/app-vite"}, "vulnerable_functions": [], "vulnerable_version_range": "<= 3.2.0"}], "withdrawn_at": null}
